import{_ as t,o as r,c as a,a0 as s}from"./chunks/framework.CzVS_xMp.js";const p=JSON.parse('{"title":"Heterogeneous Systems (Onur Mutlu)","description":"","frontmatter":{},"headers":[],"relativePath":"gpu/heterogeneous-systems/index.md","filePath":"gpu/heterogeneous-systems/index.md","lastUpdated":1788490169000}'),o={name:"gpu/heterogeneous-systems/index.md"};function n(d,e,l,i,c,u){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="heterogeneous-systems-onur-mutlu" tabindex="-1">Heterogeneous Systems (Onur Mutlu) <a class="header-anchor" href="#heterogeneous-systems-onur-mutlu" aria-label="Permalink to &quot;Heterogeneous Systems (Onur Mutlu)&quot;">​</a></h1><p>A complementary course to [PMPP](../pmpp/, used in parallel for a second pass over the classic parallel patterns behind GPU kernels. Where PMPP is the spine, this course reinforces the same patterns from a computer-architecture angle and adds irregular workloads (sparse, graph).</p><h2 id="primary-resource" tabindex="-1">Primary Resource <a class="header-anchor" href="#primary-resource" aria-label="Permalink to &quot;Primary Resource&quot;">​</a></h2><ul><li><a href="https://www.youtube.com/playlist?list=PL5Q2soXY2Zi_OwkTgEyA6tk3UsoPBH737" target="_blank" rel="noreferrer">Hands-on Acceleration on Heterogeneous Computing Systems, Fall 2021</a></li></ul><h2 id="parallel-patterns" tabindex="-1">Parallel patterns <a class="header-anchor" href="#parallel-patterns" aria-label="Permalink to &quot;Parallel patterns&quot;">​</a></h2><p>Classical building blocks behind GPU kernels. Each pattern maps directly to a case study in [<code>labs/kernels</code>](../labs/kernels/.</p><table tabindex="0"><thead><tr><th>Meeting</th><th>Topic</th><th>Kernel pattern</th></tr></thead><tbody><tr><td>2</td><td>SIMD processors and GPU architecture</td><td>execution model</td></tr><tr><td>4</td><td>GPU memory hierarchy</td><td>memory traffic and locality</td></tr><tr><td>5</td><td>GPU performance considerations</td><td>bottleneck diagnosis</td></tr><tr><td>6</td><td>Reduction</td><td>tree reductions, synchronization</td></tr><tr><td>7</td><td>Histogram</td><td>atomics, contention, privatization</td></tr><tr><td>8</td><td>Convolution</td><td>stencil/convolution memory reuse</td></tr><tr><td>9</td><td>Prefix sum / scan</td><td>parallel dependencies</td></tr><tr><td>10</td><td>Sparse matrices</td><td>irregular memory access</td></tr><tr><td>11</td><td>Graph search</td><td>divergence and irregular workloads</td></tr></tbody></table><h2 id="how-to-use-with-pmpp" tabindex="-1">How to use with PMPP <a class="header-anchor" href="#how-to-use-with-pmpp" aria-label="Permalink to &quot;How to use with PMPP&quot;">​</a></h2><ul><li>Watch a PMPP lecture on a pattern, then the matching meeting here for a second explanation.</li><li>After both, implement and profile the pattern in [<code>labs/kernels</code>](../labs/kernels/.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Add lecture notes here as the course progresses. Prefer short, measurement-oriented notes over long summaries.</p>',11)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
